package net.plainnotes.app.data
import android.content.Context
import androidx.room.Room
import androidx.test.core.app.ApplicationProvider
import kotlinx.coroutines.runBlocking
import org.junit.*
import org.junit.Assert.*
import java.time.*

abstract class HistoricalVisitContract {
    private lateinit var db:NotesDatabase
    private lateinit var repo:NotesRepository
    private val at=Instant.parse("2026-03-10T23:30:00Z")
    private val now=at.plusSeconds(86400)
    private val draft=AppointmentEntity(type="ENDO",at_utc=at.toEpochMilli(),at_zone="Pacific/Kiritimati",location=" Synthetic institution ",practitioner=" Synthetic doctor ",note=" User's own words ",remind_minutes_before=0)
    @Before fun open(){val c=ApplicationProvider.getApplicationContext<Context>();db=Room.inMemoryDatabaseBuilder(c,NotesDatabase::class.java).allowMainThreadQueries().addCallback(SchemaGuards).build();repo=NotesRepository(object:DatabaseAccess(c){override fun get(space:Space)=db})}
    @After fun close(){db.close()}
    private suspend fun create()=repo.saveHistoricalVisit(draft,now=now)
    private suspend fun snapshot()=listOf(repo.appointments(),repo.visitQuestions(),repo.visitPacks(),repo.labs(),repo.labContexts(),repo.trash())
    private suspend fun rejected(block:suspend()->Unit){try{block();fail("Unsafe change accepted")}catch(_:IllegalArgumentException){}catch(_:IllegalStateException){}catch(_:DateTimeException){}}
    @Test fun newPastVisitIsExplicitlyConfirmedAndNormalized()=runBlocking<Unit>{val v=create();assertTrue(v.id>0);assertEquals(now.toEpochMilli(),v.completed_utc);assertEquals("Synthetic doctor",v.practitioner);assertEquals("Synthetic institution",v.location);assertEquals("User's own words",v.note);assertEquals(draft.at_utc,v.at_utc);assertEquals(draft.at_zone,v.at_zone)}
    @Test fun editingKeepsIdOriginalZoneAndConfirmation()=runBlocking<Unit>{val v=create();val n=repo.saveHistoricalVisit(v.copy(type="GP",at_utc=v.at_utc-86400000,practitioner="New synthetic",note="Corrected",completed_utc=null),v,now.plusSeconds(5));assertEquals(v.id,n.id);assertEquals(v.completed_utc,n.completed_utc);assertEquals(v.at_zone,n.at_zone);assertEquals("GP",n.type);assertEquals(v.at_utc-86400000,n.at_utc)}
    @Test fun existingAppointmentIsReusedNotDuplicated()=runBlocking<Unit>{val id=repo.saveAppointment(draft);val v=repo.appointments().single();val saved=repo.saveHistoricalVisit(v,v,now);assertEquals(id,saved.id);assertNotNull(saved.completed_utc);assertEquals(1,repo.appointments().size)}
    @Test fun ordinaryPastAppointmentIsNeverAutomaticallyConfirmed()=runBlocking<Unit>{repo.saveAppointment(draft);assertNull(repo.appointments().single().completed_utc);create();assertEquals(2,repo.appointments().size);assertEquals(1,repo.appointments().count{it.completed_utc!=null})}
    @Test fun futureVisitAndInvalidZoneAndTypeRejectWithoutWrites()=runBlocking<Unit>{rejected{repo.saveHistoricalVisit(draft.copy(at_utc=now.plusSeconds(1).toEpochMilli()),now=now)};rejected{repo.saveHistoricalVisit(draft.copy(at_zone="unknown"),now=now)};rejected{repo.saveHistoricalVisit(draft.copy(type="DIAGNOSIS"),now=now)};assertTrue(repo.appointments().isEmpty())}
    @Test fun staleEditCannotOverwriteNewerData()=runBlocking<Unit>{val v=create();repo.saveHistoricalVisit(v.copy(note="Later"),v,now);val before=snapshot();rejected{repo.saveHistoricalVisit(v.copy(note="Stale"),v,now)};assertEquals(before,snapshot())}
    @Test fun retractOnlyConfirmationAndRepeatedRetractionIsSafe()=runBlocking<Unit>{val v=create();repo.retractHistoricalVisit(v,now);val after=repo.appointments().single();assertEquals(v.copy(completed_utc=null),after);val before=snapshot();rejected{repo.retractHistoricalVisit(v,now)};assertEquals(before,snapshot())}
    @Test fun deletionRestoresSameVisitQuestionsAnswersAndFrozenPack()=runBlocking<Unit>{val v=create();repo.saveVisitQuestion(VisitQuestionEntity(appointment_id=v.id,sort_order=0,text="Synthetic question",status="ASKED",answer_note="Synthetic answer"));repo.recordVisitPack(VisitPackEntity(appointment_id=v.id,generated_utc=now.toEpochMilli(),zone=v.at_zone,range_from="2026-03-01",range_to="2026-03-12",sections="FACTS,LABS",language="en",template_version=1,input_digest="a".repeat(64),facts_json="{}"));val questions=repo.visitQuestions();val packs=repo.visitPacks();repo.deleteHistoricalVisit(v,now);assertTrue(repo.appointments().isEmpty());assertTrue(repo.visitQuestions().isEmpty());assertTrue(repo.visitPacks().isEmpty());repo.restoreTrash(repo.trash().single().id,now.plusSeconds(5));assertEquals(listOf(v),repo.appointments());assertEquals(questions,repo.visitQuestions());assertEquals(packs,repo.visitPacks())}
    @Test fun staleDeleteAndDeletedEditCannotTouchOtherRows()=runBlocking<Unit>{val v=create();val other=repo.saveHistoricalVisit(draft.copy(note="Other"),now=now);repo.saveHistoricalVisit(v.copy(note="Later"),v,now);val before=snapshot();rejected{repo.deleteHistoricalVisit(v,now)};assertEquals(before,snapshot());repo.deleteHistoricalVisit(other,now);val deleted=snapshot();rejected{repo.saveHistoricalVisit(other,other,now)};assertEquals(deleted,snapshot())}
    @Test fun deletingTwiceDoesNotDuplicateTrash()=runBlocking<Unit>{val v=create();repo.deleteHistoricalVisit(v,now);val before=snapshot();rejected{repo.deleteHistoricalVisit(v,now)};assertEquals(before,snapshot());assertEquals(1,repo.trash().size)}
    @Test fun insertionAndDeletionFailuresRollBack()=runBlocking<Unit>{db.openHelper.writableDatabase.execSQL("CREATE TRIGGER synthetic_med_insert BEFORE INSERT ON appointment BEGIN SELECT RAISE(ABORT,'synthetic failure'); END");try{create();fail()}catch(_:Exception){};assertTrue(repo.appointments().isEmpty());db.openHelper.writableDatabase.execSQL("DROP TRIGGER synthetic_med_insert");val v=create();val before=snapshot();db.openHelper.writableDatabase.execSQL("CREATE TRIGGER synthetic_med_delete BEFORE DELETE ON appointment BEGIN SELECT RAISE(ABORT,'synthetic failure'); END");try{repo.deleteHistoricalVisit(v,now);fail()}catch(_:Exception){};assertEquals(before,snapshot())}
    @Test fun labsContextsAndOtherAppointmentsStayIntact()=runBlocking<Unit>{repo.saveLab(LabValueEntity(analyte_code="E2",value=100.0,unit="pg/mL",sampled_utc=at.toEpochMilli(),sampled_zone="UTC"));val beforeLabs=repo.labs();val beforeContexts=repo.labContexts();val other=repo.saveAppointment(draft.copy(note="Existing"));val v=create();repo.saveHistoricalVisit(v.copy(note="Changed"),v,now);repo.retractHistoricalVisit(repo.appointments().single{it.id==v.id},now);assertEquals(beforeLabs,repo.labs());assertEquals(beforeContexts,repo.labContexts());assertEquals(other,repo.appointments().single{it.note=="Existing"}.id);assertTrue(beforeLabs.single().id>0)}
    @Test fun encryptedBackupRetainsVisitsAndTrashAcrossAdditiveReferenceSchema()=runBlocking<Unit>{val a=create();val b=repo.saveHistoricalVisit(draft.copy(note="Another"),now=now);repo.deleteHistoricalVisit(a,now);val before=snapshot();val pwd="synthetic-med-password".toCharArray();repo.restoreBackup(repo.exportBackup(pwd),pwd);assertEquals(before,snapshot());assertEquals(b,repo.appointments().single());assertEquals(22,db.openHelper.writableDatabase.version);assertEquals(16,RecordBackupCompatibility.SCHEMA)}

    @Test fun editsCannotMoveConfirmedVisitIntoFuture()=runBlocking<Unit>{val v=create();val before=snapshot();rejected{repo.saveHistoricalVisit(v.copy(at_utc=now.plusSeconds(10).toEpochMilli()),v,now)};assertEquals(before,snapshot())}
    @Test fun existingUnconfirmedVisitCanBeExplicitlyConfirmedWithoutChangingOtherFields()=runBlocking<Unit>{repo.saveAppointment(draft);val old=repo.appointments().single();val v=repo.saveHistoricalVisit(old,old,now);assertEquals(old.copy(completed_utc=now.toEpochMilli()),v)}
    @Test fun fileDatabaseReopenRetainsOccurrenceZoneAndConfirmation()=runBlocking<Unit>{val c=ApplicationProvider.getApplicationContext<Context>();val name="synthetic-med01-reopen";db.close();c.deleteDatabase(name);db=Room.databaseBuilder(c,NotesDatabase::class.java,name).allowMainThreadQueries().addCallback(SchemaGuards).build();repo=NotesRepository(object:DatabaseAccess(c){override fun get(space:Space)=db});val v=create();db.close();db=Room.databaseBuilder(c,NotesDatabase::class.java,name).allowMainThreadQueries().addCallback(SchemaGuards).build();repo=NotesRepository(object:DatabaseAccess(c){override fun get(space:Space)=db});assertEquals(listOf(v),repo.appointments());db.close();c.deleteDatabase(name)}
    @Test fun pinnedMedicalStoreCannotWriteToOtherSpace()=runBlocking<Unit>{val c=ApplicationProvider.getApplicationContext<Context>();val decoy=Room.inMemoryDatabaseBuilder(c,NotesDatabase::class.java).allowMainThreadQueries().addCallback(SchemaGuards).build();try{val access=object:DatabaseAccess(c){override fun get(space:Space)=if(space==Space.PRIMARY)db else decoy};val movable=NotesRepository(access);val pinned=movable.pinnedTo(Space.PRIMARY);movable.select(Space.DECOY);val v=pinned.saveHistoricalVisit(draft,now=now);assertEquals(listOf(v),pinned.appointments());assertTrue(movable.appointments().isEmpty());assertEquals(Space.DECOY,movable.space)}finally{decoy.close()}}
    @Test fun legacyUnknownVisitCategoryIsPreservedUntilExplicitlyChanged()=runBlocking<Unit>{repo.saveAppointment(draft.copy(type="CHECKUP"));val old=repo.appointments().single();val saved=repo.saveHistoricalVisit(old.copy(practitioner="Corrected synthetic"),old,now);assertEquals("CHECKUP",saved.type);assertEquals(old.id,saved.id);assertNotNull(saved.completed_utc)}
}
